  detail.after(pair);const dialogs=document.createElement('div');dialogs.innerHTML=`<dialog id="videoConfigDialog" class="video-dialog"><form id="videoConfigForm"><header><h2>视频生成服务</h2><button type="button" data-close aria-label="关闭视频服务设置">×</button></header><p id="videoProviderHelp">分镜视频生成 · 与图片服务独立配置</p><label for="videoProvider">视频服务</label><select id="videoProvider"><option value="zhipu">智谱 CogVideoX-3</option><option value="minimax">MiniMax 海螺</option></select><label for="videoModel" id="videoModelLabel" hidden>视频模型</label><select id="videoModel" hidden><option value="MiniMax-Hailuo-2.3">MiniMax-Hailuo-2.3</option><option value="MiniMax-Hailuo-2.3-Fast">MiniMax-Hailuo-2.3-Fast</option></select><label for="videoApiKey" id="videoApiKeyLabel">API 密钥</label><input id="videoApiKey" type="password" autocomplete="off" required minlength="8" placeholder="填写已开通视频模型的密钥"><small>密钥仅在本机加密保存。内容策划使用现有图片服务。</small><p id="videoConfigStatus" role="status"></p><button type="submit" class="video-dialog-primary">保存配置</button></form></dialog><dialog id="videoPickerDialog" class="video-dialog video-picker-dialog"><header><h2>选择同款创作素材</h2><button type="button" data-close aria-label="关闭图片选择">×</button></header><p>可加入整体、花型和工艺细节图，分镜可单独指定素材。</p><div id="videoPickerGrid"></div><p id="videoPickerStatus" role="status"></p><button type="button" id="videoPickerDone" class="video-dialog-primary">完成选择</button></dialog>`;document.body.append(dialogs);setup(pair);return true;
