  function renderPreview(){const j=selected(),shot=previewShot!=null?j?.shots?.[previewShot]:null,video=shot?.url||(j?.status==='completed'?j.url:null),poster=shot?.frameUrl||j?.poster||sources[sourceIndex]?.image,key=[j?.id||'',j?.status||'',previewShot,video||'',poster||''].join('|');if(key===previewKey)return;previewKey=key;$('videoPlayer').pause();$('videoPlayer').hidden=!video;$('videoSourcePreview').hidden=!!video||!poster;$('videoEmpty').hidden=!!poster||!!video;$('videoPreviewBadge').hidden=!!video||!poster;$('videoPreviewBadge').textContent=shot?.frameUrl||j?.shots?.[0]?.frameUrl?'全新创意场景 · 花型参考重创作':'产品参考 · 不作为视频首帧';if(video){$('videoPlayer').src=video;$('videoPlayer').poster=poster||'';}else{$('videoPlayer').removeAttribute('src');$('videoPlayer').load();if(poster)$('videoSourcePreview').src=poster;}$('videoDownload').hidden=!j||j.status!=='completed';if(j?.status==='completed'){$('videoDownload').href=j.url;$('videoDownload').download='织景内容短片_'+j.id.slice(0,8)+'.mp4';}$('videoResume').hidden=!j?.canResume;$('videoPlaybackStatus').textContent=j?.message||'';$('videoPreviewCaption').textContent=j?(shot?'第 '+(previewShot+1)+' 镜 · '+shot.title:(j.storyboard?.title||'历史视频')+' · '+j.duration+' 秒'):sources.length?'创作素材 '+(sourceIndex+1)+' · '+sources[sourceIndex].name:'内容策划 → 分镜创作 → 剪辑成片';}
